#!/usr/bin/env python3
"""Fill declared DOCX {{FIELD}} placeholders without editing inputs.
- Replaces placeholders even when split across runs within a paragraph.
- Processes body, nested tables, and all active headers/footers.
- Conditional {{IF_RELOCATION}}...{{END_IF_RELOCATION}} governed ONLY by
  RELOCATION_PACKAGE; content kept iff that field equals exactly "Yes".
- No aliases/fallbacks. Missing required field -> exit nonzero.
- No installs, no network, no macros, no cross-paragraph tokens.
"""
import sys, re, json, zipfile, shutil, os

TEMPLATE = "inputs/offer_letter_template.docx"
DATA = "inputs/employee_data.json"
OUT = "output/offer_letter_filled.docx"

COND_NAME = "RELOCATION"  # IF_RELOCATION / END_IF_RELOCATION
COND_GOVERNOR = "RELOCATION_PACKAGE"

PH = re.compile(r"\{\{([A-Z_]+)\}\}")

def die(msg):
    sys.stderr.write("ERROR: " + msg + "\n")
    sys.exit(2)

def load_data():
    with open(DATA, encoding="utf-8") as f:
        return json.load(f)

# Parse a paragraph XML into an ordered list of run-text segments so we can
# operate on the concatenated text but write results back into real <w:t>.
WT = re.compile(r"(<w:t\b[^>]*>)(.*?)(</w:t>)", re.S)

def transform_paragraph(p_xml, resolve):
    """resolve(name)->str for a plain placeholder; returns new paragraph xml.
    Also applies conditional removal within this paragraph only."""
    # Gather the <w:t> segments
    segs = list(WT.finditer(p_xml))
    if not segs:
        return p_xml
    full = "".join(m.group(2) for m in segs)
    if "{{" not in full:
        return p_xml

    # --- apply conditional (same-paragraph) ---
    new_full = full
    # IF ... END_IF block
    block_re = re.compile(
        r"\{\{IF_" + COND_NAME + r"\}\}(.*?)\{\{END_IF_" + COND_NAME + r"\}\}", re.S)
    def cond_sub(m):
        keep = resolve(COND_GOVERNOR, conditional=True) == "Yes"
        return m.group(1) if keep else ""
    new_full = block_re.sub(cond_sub, new_full)

    # --- plain placeholders ---
    def ph_sub(m):
        name = m.group(1)
        return resolve(name)
    new_full = PH.sub(ph_sub, new_full)

    if new_full == full:
        return p_xml

    # Redistribute new_full across existing <w:t> segments: put everything in
    # the first segment, empty the rest (preserves run/table structure & props).
    out = []
    last = 0
    first_done = False
    for i, m in enumerate(segs):
        out.append(p_xml[last:m.start()])
        if not first_done:
            out.append(m.group(1) + xml_escape(new_full) + m.group(3))
            first_done = True
        else:
            out.append(m.group(1) + m.group(3))
        last = m.end()
    out.append(p_xml[last:])
    return "".join(out)

def xml_escape(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))

P_RE = re.compile(r"<w:p\b.*?</w:p>", re.S)

def process_part(xml, resolve):
    def repl(m):
        return transform_paragraph(m.group(0), resolve)
    return P_RE.sub(repl, xml)

def collect_needed(parts):
    """Scan all parts for referenced field names (plain + governor if cond used)."""
    needed = set()
    cond_used = False
    for xml in parts:
        for p in P_RE.finditer(xml):
            full = "".join(WT_m.group(2) for WT_m in WT.finditer(p.group(0)))
            if "{{IF_" + COND_NAME + "}}" in full:
                cond_used = True
            for name in PH.findall(full):
                if name.startswith("IF_") or name.startswith("END_IF_"):
                    continue
                needed.add(name)
    if cond_used:
        needed.add(COND_GOVERNOR)
    return needed, cond_used

def main():
    data = load_data()
    z = zipfile.ZipFile(TEMPLATE)
    names = z.namelist()

    target_parts = [n for n in names
                    if n == "word/document.xml"
                    or re.fullmatch(r"word/(header|footer)\d+\.xml", n)]
    part_xml = {n: z.read(n).decode("utf-8") for n in target_parts}

    needed, cond_used = collect_needed(part_xml.values())

    # Validate required fields exist and are non-empty (governor required if cond used)
    missing = []
    for name in sorted(needed):
        if name not in data or data[name] is None or str(data[name]) == "":
            missing.append(name)
    if missing:
        die("missing required field(s): " + ", ".join(missing))

    def resolve(name, conditional=False):
        if name not in data:
            die("missing required field: " + name)
        return str(data[name])

    for n in target_parts:
        part_xml[n] = process_part(part_xml[n], resolve)

    # Sanity: no leftover declared placeholders in processed parts
    for n, xml in part_xml.items():
        for p in P_RE.finditer(xml):
            full = "".join(m.group(2) for m in WT.finditer(p.group(0)))
            leftover = PH.findall(full)
            if leftover:
                die("unresolved placeholder(s) in %s: %s" % (n, leftover))

    os.makedirs("output", exist_ok=True)
    # Rewrite zip, copying untouched entries verbatim, replacing targets.
    with zipfile.ZipFile(OUT, "w", zipfile.ZIP_DEFLATED) as zo:
        for item in z.infolist():
            if item.filename in part_xml:
                zo.writestr(item, part_xml[item.filename].encode("utf-8"))
            else:
                zo.writestr(item, z.read(item.filename))
    z.close()
    print("OK wrote", OUT)

if __name__ == "__main__":
    main()

